sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float exposure;
uniform float gamma;
uniform float lift;
uniform float rolloff;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    s = s * exp2(exposure) + float3(lift);
    s = pow(max(s, float3(0.0)), float3(1.0 / max(gamma, 0.01)));
    float3 rolled = s / (1.0 + rolloff * s);
    float3 o = mix(s, rolled * (1.0 + rolloff), rolloff);
    return fin(c, float4(saturate(o) * c.a, c.a), opacity);
}
